        });
      },
    });
  }

  private spawnSpark(
    scene: Phaser.Scene,
    x: number, y: number,
    opts: { color: number; radius: number; tx: number; ty: number; duration: number; endScale?: number },
  ): void {
    ensureGlowDot(scene);
    const initScale = opts.radius / 10;
