import Phaser from 'phaser';
import { ensureGlowDot } from './glowDot';

export interface BurstOpts {
  /** 파티클 색상 (배열 시 랜덤 선택) */
  tint: number | number[];
  /** 파티클 수 (기본: 8) */
  count?: number;
  /** 최소 속도 px/s (기본: 40) */
  minSpeed?: number;
  /** 최대 속도 px/s (기본: 130) */
  maxSpeed?: number;
  /** 시작 스케일 (기본: 0.28) */
  scale?: number;
  /** 수명 ms (기본: 380) */
  lifespan?: number;
  /** 렌더링 depth (기본: 200) */
  depth?: number;
  /** true → 위쪽 방향 편향 (불꽃/연기 효과) */
  upward?: boolean;
}

/**
 * glow_dot 텍스처 기반 ADD 블렌드 파티클 버스트.
 *
 * 기존 for-loop + scene.add.image() + tween 패턴을 대체:
 * ParticleEmitter는 내부적으로 오브젝트 풀링 + WebGL 배치 드로우를 사용하므로
 * 동일한 수의 파티클을 훨씬 적은 JS 객체로 처리한다.
 */
export function burst(
  scene: Phaser.Scene,
  x: number,
  y: number,
  opts: BurstOpts,
): void {
  ensureGlowDot(scene);
  const lifespan = opts.lifespan ?? 380;
  const count    = opts.count ?? 8;

  const emitter = scene.add.particles(x, y, 'glow_dot', {
    speed:     { min: opts.minSpeed ?? 40, max: opts.maxSpeed ?? 130 },
    angle:     opts.upward ? { min: 220, max: 320 } : { min: 0, max: 360 },
    scale:     { start: opts.scale ?? 0.28, end: 0 },
    alpha:     { start: 1, end: 0 },
    lifespan,
    // Phaser runtime이 number[] 를 처리하므로 타입 단언으로 전달
    tint:      opts.tint as unknown as number,
    blendMode: Phaser.BlendModes.ADD,
    depth:     opts.depth ?? 200,
  });

  emitter.explode(count);
  // 모든 파티클의 수명이 끝난 뒤 이미터 정리
  scene.time.delayedCall(lifespan + 200, () => {
    if (emitter.active) emitter.destroy();
  });
}

