from PIL import Image

img = Image.open('/Users/johyunduk/Projects/ddong-avoid-game/public/assets/sprites/skills/red_lightning_sp.png')
fh, fw = 512, 704

# frame[1,1] — row1 col1 (충격파 시작 프레임)
frame = img.crop((fw, fh, fw*2, fh*2))

last_bright_y = 0
for y in range(fh):
    for x in range(fw):
        px = frame.getpixel((x, y))
        # RGBA: alpha>64, or RGB: any channel>30
        if img.mode == 'RGBA':
            if px[3] > 64:
                last_bright_y = y
        else:
            if max(px[:3]) > 30:
                last_bright_y = y

print(f'mode: {img.mode}')
print(f'콘텐츠 최하단 Y: {last_bright_y} / 512 = {last_bright_y/512*100:.1f}%')
